rel=[(r-5,c-26) for r,c in orig]
print("orig shape rel:")
minr=min(r for r,c in rel); minc=min(c for r,c in rel)
for r,c in sorted(rel): print((r,c))
for i in range(minr, max(r for r,c in rel)+1):
    print(''.join('8' if (i,j) in rel else '.' for j in range(minc, max(c for r,c in rel)+1)))
print()
arelr=[(r-2,c-5) for r,c in added]
for i in range(max(r for r,c in arelr)+1):
    print(''.join('8' if (i,j) in arelr else '.' for j in range(max(c for r,c in arelr)+1)))

T={(0,0),(1,-1),(2,-2),(3,-4),(3,-3),(4,-4),(4,-2),(5,-2)}
added_set={tuple(x) for x in added}
orig_set={tuple(x) for x in orig}
allpos=added_set|orig_set
